// Função para retry com backoff exponencial
async function retryWithBackoff(fn, maxRetries = 3, baseDelay = 1000) {
  let lastError;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      // Se é o último attempt, lança o erro
      if (attempt === maxRetries) {
        throw lastError;
      }
      // Calcular delay com backoff exponencial
      const delay = baseDelay * Math.pow(2, attempt);
      console.log(`❌ Tentativa ${attempt + 1} falhou: ${lastError.message}. Tentando novamente em ${delay}ms...`);
      // Aguardar antes da próxima tentativa
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}
// Função para fazer requisições à API do OpenRouter com fallback de modelo
async function makeOpenRouterRequestWithModel(prompt, model) {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
  if (!apiKey) {
    throw new Error('OPENROUTER_API_KEY not set');
  }
  const fetchStart = Date.now();
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
      'X-Title': 'momma-manual'
    },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: prompt }
      ],
      temperature: 0.1,
      response_format: { type: 'json_object' }
    })
  });
  if (!response.ok) {
    const errorText = await response.text().catch(() => 'Erro desconhecido');
    console.error(`❌ OpenRouter API error with model ${model}: ${response.status} - ${errorText}`);
    logEvent('warning', 'fallback_api_error', { model, status: response.status, errorText });
    // Diferentes tipos de erro
    if (response.status === 502) {
      throw new Error(`OpenRouter API temporariamente indisponível (502 Bad Gateway). Tentando novamente...`);
    } else if (response.status === 503) {
      throw new Error(`OpenRouter API sobrecarregada (503 Service Unavailable). Tentando novamente...`);
    } else if (response.status === 429) {
      throw new Error(`Rate limit atingido (429 Too Many Requests). Tentando novamente...`);
    } else if (response.status >= 500) {
      throw new Error(`Erro interno do servidor OpenRouter (${response.status}). Tentando novamente...`);
    } else {
      // Erros 4xx não devem ser retentados
      throw new Error(`OpenRouter API error: ${response.status} - ${errorText}`);
    }
  }
  const data = await response.json();
  const durationMs = Date.now() - fetchStart;
  return { data, durationMs, model };
}
// Função para fazer requisições à API do OpenRouter com retry e fallback de modelo
// Returns { data, durationMs, model } from makeOpenRouterRequestWithModel
async function makeOpenRouterRequest(prompt) {
  let lastError;
  for (const model of FALLBACK_MODELS) {
    try {

      const res = await retryWithBackoff(async () => {
        return await makeOpenRouterRequestWithModel(prompt, model);
      }, 3, 2000);
      return res;
    } catch (err) {
      lastError = err;
      logEvent('warning', 'fallback_model_fail', { model, error: err instanceof Error ? err.message : String(err) });
      continue;
    }
  }
  throw lastError || new Error('Todos os modelos de fallback falharam');
}
// Streaming de raciocínio via SSE com fallback de modelo
async function streamOpenRouterReasoning(prompt, models, tracer?: EdgeTracer, metrics?: EdgeMetrics) {
  const encoder = new TextEncoder();
  let chosenModelIndex = -1;
  let contentBuffer = '';
  let reasoningBuffer = '';
  let normalizedReasoningSent = '';
  let seenTextDelta = false;
  let modelAnnounced = false;
  const stream = new ReadableStream({
    async start(controller) {
      // Helper para enviar evento SSE
      const sendEvent = (event, data) => {
        const payload = `event: ${event}\n` + `data: ${JSON.stringify(data)}\n\n`;
        controller.enqueue(encoder.encode(payload));
      };
      sendEvent('status', { message: 'Processando IA...' });
      // Keepalive: evita que browser/proxy encerre SSE por inatividade enquanto o modelo processa
      const keepaliveTimer = setInterval(() => {
        try { sendEvent('status', { message: 'Aguardando IA...', heartbeat: true }); } catch (_) {}
      }, 20000);
      // Tenta modelos em sequência
      for (let i = 0; i < models.length; i++) {
        const model = models[i];
        try {
          chosenModelIndex = i;
          const apiKeyStream = Deno.env.get('OPENROUTER_API_KEY');
          if (!apiKeyStream) {
            throw new Error('OPENROUTER_API_KEY not set');
          }
          if (isGrokModel(model)) {
            const grokFetchStart = Date.now();
            const grokAbort = new AbortController();
            const grokTimeoutId = setTimeout(() => grokAbort.abort(), 60000);
            let res: Response;
            try {
              res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
                method: 'POST',
                headers: {
                  'Authorization': `Bearer ${apiKeyStream}`,
                  'Content-Type': 'application/json',
                  'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
                  'X-Title': 'momma-manual'
                },
                body: JSON.stringify({
                  model,
                  messages: [ { role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: prompt } ],
                  temperature: 0.1,
                  response_format: { type: 'json_object' }
                }),
                signal: grokAbort.signal
              });
            } finally {
              clearTimeout(grokTimeoutId);
            }
            if (!res.ok) {
              const txt = await res.text().catch(() => '');
              logEvent('warning', 'fallback_model_fail', { model, status: res.status, errorText: txt });
              throw new Error(`Falha request ${model}: ${res.status} ${txt}`);
            }
            const data = await res.json();
            const grokDurationMs = Date.now() - grokFetchStart;
            const content = data?.choices?.[0]?.message?.content ?? '';
            logEvent('info', 'openrouter_response', { model, contentLength: content.length, content });
            // Record telemetry metrics for Grok non-streaming response
            if (metrics && data?.usage) {
              const grokInputTokens = data.usage.prompt_tokens ?? 0;
              const grokOutputTokens = data.usage.completion_tokens ?? 0;
              metrics.recordLlmCall({
                model: data.model || model,
                provider: 'openrouter',
                operation: 'requisition-parse',
                inputTokens: grokInputTokens,
                outputTokens: grokOutputTokens,
                durationMs: grokDurationMs,
              });
            }
            let parsedResponse = null;
            try {
              let clean = content.trim();
              if (clean.startsWith('```')) {
                clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
              }
              parsedResponse = JSON.parse(clean);
            } catch {
              sendEvent('error', { message: 'Erro ao processar resposta da IA' });
              logEvent('error', 'parse_error', { model, content });
              throw new Error('Erro ao processar resposta da IA');
            }
            try {
              const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
              if (categories.length > 0) {
                const flattened = categories.flatMap((cat) => Array.isArray(cat?.items) ? cat.items.map((it) => ({
                  name: String(it?.name || '').trim(),
                  source_text: it?.source_text ? String(it.source_text) : undefined,
                  requested: Number(it?.requested ?? 1),
                  sent: it?.sent ?? null,
                  observation: it?.observation ? String(it.observation) : undefined,
                  category: String(cat?.category || '').trim()
                })) : []);
                parsedResponse.items = flattened;
                const totalItems = flattened.length;
                const totalRequested = flattened.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
                parsedResponse.meta = parsedResponse.meta || {
                  total_items: totalItems,
                  total_requested: totalRequested
                };
              } else if (!Array.isArray(parsedResponse?.items)) {
                parsedResponse.items = [];
                parsedResponse.categories = [];
                parsedResponse.meta = parsedResponse.meta || { total_items: 0, total_requested: 0 };
              }
            } catch (_) {}
            sendEvent('status', { message: 'Modelo selecionado', model, final: true });
            sendEvent('result', { ...parsedResponse, final_model: model });
            logEvent('info', 'result_emit', { model, items: parsedResponse?.items?.length ?? 0, categories: parsedResponse?.categories?.length ?? 0, meta: parsedResponse?.meta });
            // Fire-and-forget: flush Grok streaming telemetry
            if (tracer || metrics) {
              Promise.all([tracer?.flush(), metrics?.flush()].filter(Boolean)).catch(() => {});
            }
            clearInterval(keepaliveTimer);
            controller.close();
            return;
          }
          const streamFetchStart = Date.now();
          let streamPromptTokens = 0;
          let streamCompletionTokens = 0;
          const streamModelAbort = new AbortController();
          const streamModelTimeoutId = setTimeout(() => streamModelAbort.abort(), 90000);
          let res: Response;
          try {
            res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${apiKeyStream}`,
                'Content-Type': 'application/json',
                'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
                'X-Title': 'momma-manual',
                'Accept': 'text/event-stream'
              },
              body: JSON.stringify({
                model,
                messages: [ { role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: prompt } ],
                temperature: 0.1,
                response_format: { type: 'json_object' },
                stream: true,
                streamOptions: { includeUsage: true }
              }),
              signal: streamModelAbort.signal
            });
          } finally {
            clearTimeout(streamModelTimeoutId);
          }
          if (!res.ok || !res.body) {
            const txt = await res.text().catch(() => '');
            logEvent('warning', 'fallback_stream_fail', { model, status: res.status, errorText: txt });
            throw new Error(`Falha streaming ${model}: ${res.status} ${txt}`);
          }
          const reader = res.body.getReader();
          const decoder = new TextDecoder();
          let buf = '';
          let eventCount = 0;
          let hasReasoningEvents = false;
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            buf += decoder.decode(value, {
              stream: true
            });
            const parts = buf.split('\n\n');
            // Processar todos os blocos completos
            while (parts.length > 1) {
              const block = parts.shift(); // remove primeiro bloco
              const lines = block.split('\n');
              let eventName = 'message';
              let dataLine = '';
              for (const line of lines) {
                if (line.startsWith('event:')) eventName = line.slice(6).trim();
                if (line.startsWith('data:')) dataLine = line.slice(5).trim();
              }
              eventCount++;

              if (dataLine === '[DONE]') {
                continue;
              }
              if (dataLine) {
                try {
                  const json = JSON.parse(dataLine);
                  const choice = json?.choices?.[0] || {};
                  const delta = choice?.delta || {};
                  const message = choice?.message || {};
                  const usage = json?.usage || {};
                  const reasoning = delta?.reasoning || delta?.reasoning_content || message?.reasoning || json?.reasoning || null;
                  const reasoningDetails = delta?.reasoning_details || message?.reasoning_details || json?.reasoning_details || null;
                  if (!modelAnnounced && (reasoning || reasoningDetails || typeof delta?.content === 'string' || typeof message?.content === 'string')) {
                    modelAnnounced = true;
                    sendEvent('status', { message: 'Modelo selecionado', model, final: true });
                  }
                  if (reasoning) { hasReasoningEvents = true; }
                  if (reasoningDetails) { hasReasoningEvents = true; }
                  if (reasoning && !isGrokModel(model)) {
                    let chunkText = typeof reasoning === 'string' ? reasoning : JSON.stringify(reasoning);
                    chunkText = chunkText.replace(/\*+/g, '');
                    reasoningBuffer = appendOverlapDedup(reasoningBuffer, chunkText);
                    const normalized = normalizeReasoningText(reasoningBuffer);
                    const diff = normalized.slice(normalizedReasoningSent.length);
                    if (diff) {
                      sendEvent('reasoning', {
                        text: diff
                      });
                      normalizedReasoningSent = normalized;
                    }
                  }
                  if (reasoningDetails && !isGrokModel(model)) {
                    sendEvent('reasoning_details', {
                      details: reasoningDetails
                    });
                  }
                  if (typeof delta?.content === 'string') {
                    contentBuffer += delta.content;
                    sendEvent('delta', {
                      content: delta.content
                    });
                    if (delta.content.trim()) seenTextDelta = true;
                  }
                  if (!seenTextDelta && typeof message?.content === 'string' && message.content.trim()) {
                    contentBuffer += message.content;
                    sendEvent('delta', {
                      content: message.content
                    });
                  }
                  if (usage) {
                    const completionDetails = usage.completion_tokens_details || usage.completionTokensDetails || {};
                    const usagePrompt = usage.prompt_tokens ?? usage.promptTokens ?? 0;
                    const usageCompletion = usage.completion_tokens ?? usage.completionTokens ?? usage.output_tokens ?? 0;
                    // Capture latest non-zero usage for metrics recording
                    if (usagePrompt > 0) streamPromptTokens = usagePrompt;
                    if (usageCompletion > 0) streamCompletionTokens = usageCompletion;
                    sendEvent('usage', {
                      reasoningTokens: usage.reasoningTokens ?? usage.reasoning_tokens ?? completionDetails.reasoning_tokens ?? null,
                      totalTokens: usage.total_tokens ?? usage.totalTokens ?? null,
                      completionTokens: usageCompletion || null,
                      promptTokens: usagePrompt || null
                    });
                  }
                } catch (_) {
                  console.debug('[SSE] non-JSON chunk');
                }
              }
            }
            // Mantém o resto no buffer
            buf = parts[0] || '';
          }
          // Ao finalizar, enviar resultado
          let parsedResponse = null;
          try {
            let cleanResponse = contentBuffer.trim();
            if (cleanResponse.startsWith('```json')) {
              cleanResponse = cleanResponse.replace(/^```json\s*/, '').replace(/\s*```$/, '');
            }
            parsedResponse = JSON.parse(cleanResponse);
          } catch {
            sendEvent('error', {
              message: 'Erro ao processar resposta da IA'
            });
            throw new Error('Erro ao processar resposta da IA');
          }
          try {
            const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
            if (categories.length > 0) {
              const flattened = categories.flatMap((cat) => Array.isArray(cat?.items) ? cat.items.map((it) => ({
                name: repairItemName(String(it?.name || '').trim(), String(cat?.category || '')),
                source_text: it?.source_text ? String(it.source_text) : undefined,
                requested: Number(it?.requested ?? 1),
                sent: it?.sent ?? null,
                observation: undefined, // IA NÃO anota observação (decisão de produto) — sempre vazio
                category: String(cat?.category || '').trim()
              })) : []);
              parsedResponse.items = flattened;
              const totalItems = flattened.length;
              const totalRequested = flattened.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
              parsedResponse.meta = parsedResponse.meta || {
                total_items: totalItems,
                total_requested: totalRequested
              };
            } else if (!Array.isArray(parsedResponse?.items)) {
              parsedResponse.items = [];
              parsedResponse.categories = [];
              parsedResponse.meta = parsedResponse.meta || {
                total_items: 0,
                total_requested: 0
              };
            }
          } catch (e) { console.debug('[SSE] normalize categories skip'); }
          // Record telemetry metrics for streaming response
          if (metrics && (streamPromptTokens > 0 || streamCompletionTokens > 0)) {
            const streamDurationMs = Date.now() - streamFetchStart;
            metrics.recordLlmCall({
              model: model,
              provider: 'openrouter',
              operation: 'requisition-parse',
              inputTokens: streamPromptTokens,
              outputTokens: streamCompletionTokens,
              durationMs: streamDurationMs,
            });
          }
          sendEvent('result', { ...parsedResponse, final_model: model });
          logEvent('info', 'result_emit', { model, items: parsedResponse?.items?.length ?? 0, categories: parsedResponse?.categories?.length ?? 0, meta: parsedResponse?.meta });
          // Fire-and-forget: flush streaming telemetry
          if (tracer || metrics) {
            Promise.all([tracer?.flush(), metrics?.flush()].filter(Boolean)).catch(() => {});
          }
          clearInterval(keepaliveTimer);
          controller.close();
          return;
        } catch (err) {
          sendEvent('status', {
            message: `Falha com modelo atual. Motivo: ${err instanceof Error ? err.message : String(err)}`
          });
          logEvent('warning', 'fallback_stream_error', { model, error: err instanceof Error ? err.message : String(err) });
          continue;
        }
      }
      sendEvent('error', { message: 'Todos os modelos de IA falharam ao processar a requisição. Tente novamente.' });
      logEvent('warning', 'stream_all_failed', { models });
      clearInterval(keepaliveTimer);
      controller.close();
    }
  });
  return new Response(stream, {
    headers: {
      ...corsHeaders,
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
      ...(tracer ? { 'traceparent': tracer.getResponseTraceparent() } : {}),
    }
  });
}
serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      headers: corsHeaders
    });
  }
  const tracer = new EdgeTracer(req, { serviceName: 'gidape-edge-requisition-ai' });
  const metrics = new EdgeMetrics({ serviceName: 'gidape-edge-requisition-ai' });
  const rootSpan = tracer.startSpan('process-requisition-ai');
  try {
    const url = new URL(req.url);
    const streamRequested = url.searchParams.get('stream') === '1' || (req.headers.get('accept') || '').includes('text/event-stream');
    const { manualRequest, productCatalog } = await req.json();
    // Build prompt: raw text + optional catalog for exact name matching
    let prompt = manualRequest;
    if (Array.isArray(productCatalog) && productCatalog.length > 0) {
      const catalogLines = productCatalog
        .slice(0, 300) // cap to avoid token overflow
        .map((p: { name: string }) => p.name)
        .join('\n');
      prompt = `${manualRequest}\n\n---\n[CATÁLOGO DE PRODUTOS]\nUse os nomes abaixo como referência. Prefira o nome exato do catálogo ao reconstruir o nome do produto:\n${catalogLines}`;
    }
    logEvent('info', 'input_received', { contentLength: String(prompt || '').length, hasCatalog: Array.isArray(productCatalog) && productCatalog.length > 0 });
    if (streamRequested) {
      rootSpan.setAttribute('request.mode', 'stream');
      rootSpan.end();
      // Fire-and-forget: flush traces/metrics collected so far
      Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
      return await streamOpenRouterReasoning(prompt, FALLBACK_MODELS, tracer, metrics);
    }
    // chamada não-stream
    rootSpan.setAttribute('request.mode', 'non-stream');
    const llmSpan = tracer.startSpan('llm-call-openrouter', rootSpan.spanId);
    const result = await makeOpenRouterRequest(prompt);
    const data = result.data;
    const llmDurationMs = result.durationMs;
    const actualModel = data?.model || result.model;
    llmSpan.setAttribute('llm.model', actualModel);
    llmSpan.setAttribute('llm.provider', 'openrouter');
    // Record token usage metrics
    const usage = data?.usage;
    if (usage) {
      const inputTokens = usage.prompt_tokens ?? 0;
      const outputTokens = usage.completion_tokens ?? 0;
      llmSpan.setAttribute('llm.usage.input_tokens', inputTokens);
      llmSpan.setAttribute('llm.usage.output_tokens', outputTokens);
      llmSpan.setAttribute('llm.usage.total_tokens', usage.total_tokens ?? (inputTokens + outputTokens));
      metrics.recordLlmCall({
        model: actualModel,
        provider: 'openrouter',
        operation: 'requisition-parse',
        inputTokens,
        outputTokens,
        durationMs: llmDurationMs,
      });
    }
    llmSpan.end();
    const aiResponse = data.choices[0].message.content;
    logEvent('info', 'openrouter_response', { model: actualModel, contentLength: aiResponse.length, content: aiResponse });
    // Parse AI response
    let parsedResponse;
    try {
      // Clean the response by removing markdown formatting
      let cleanResponse = aiResponse.trim();
      if (cleanResponse.startsWith('```json')) {
        cleanResponse = cleanResponse.replace(/^```json\s*/, '').replace(/\s*```$/, '');
      }
      parsedResponse = JSON.parse(cleanResponse);
    } catch (e) {
      // Fallback parsing if AI doesn't return perfect JSON
      logEvent('error', 'parse_error', { model: null, content: aiResponse });
      throw new Error('Erro ao processar resposta da IA');
    }
    // Compatibilidade: se houver categorias, gerar também um array flatten "items"
    try {
      const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
      if (categories.length > 0) {
        const flattened = categories.flatMap((cat) => Array.isArray(cat?.items) ? cat.items.map((it) => ({
          name: repairItemName(String(it?.name || '').trim(), String(cat?.category || '')),
          source_text: it?.source_text ? String(it.source_text) : undefined,
          requested: Number(it?.requested ?? 1),
          sent: it?.sent ?? null,
          observation: undefined, // IA NÃO anota observação (decisão de produto) — sempre vazio
          category: String(cat?.category || '').trim()
        })) : []);
        parsedResponse.items = flattened;
        // Meta fallback
        const totalItems = flattened.length;
        const totalRequested = flattened.reduce((sum, it) => sum + (Number(it.requested) || 0), 0);
        parsedResponse.meta = parsedResponse.meta || {
          total_items: totalItems,
          total_requested: totalRequested
        };
      } else if (!Array.isArray(parsedResponse?.items)) {
        // Se não houver nem categorias nem items válidos, normaliza estrutura vazia
        parsedResponse.items = [];
        parsedResponse.categories = [];
        parsedResponse.meta = parsedResponse.meta || {
          total_items: 0,
          total_requested: 0
        };
      }
    } catch (flattenError) {
      console.warn('Falha ao normalizar categorias/items:', flattenError);
    }
    logEvent('info', 'result_return', { items: parsedResponse?.items?.length ?? 0, categories: parsedResponse?.categories?.length ?? 0, meta: parsedResponse?.meta });
    rootSpan.end();
    // Fire-and-forget: flush traces and metrics
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
    return new Response(JSON.stringify(parsedResponse), {
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  } catch (error) {
    console.error('❌ Error in process-requisition-ai:', error);
    logEvent('error', 'fatal', { error: error instanceof Error ? error.message : String(error) });
    rootSpan.endWithError(error instanceof Error ? error.message : String(error));
    // Fire-and-forget: flush traces and metrics even on error
    Promise.all([tracer.flush(), metrics.flush()]).catch(() => {});
    // Determinar o status code baseado no tipo de erro
    let statusCode = 500;
    let errorMessage = 'Erro interno do servidor';
    if (error instanceof Error) {
      if (error.message.includes('OpenRouter API error: 4')) {
        // Erros 4xx são erros do cliente
        statusCode = 400;
        errorMessage = 'Erro na requisição para a API de IA';
      } else if (error.message.includes('OpenRouter') || error.message.includes('502') || error.message.includes('503')) {
        // Erros de API externa
        statusCode = 502;
        errorMessage = 'Serviço de IA temporariamente indisponível. Tente novamente em alguns minutos.';
      } else if (error.message.includes('Erro ao processar resposta da IA')) {
        // Erro de parsing
        statusCode = 422;
        errorMessage = 'Erro ao processar resposta da IA';
      } else {
        errorMessage = error.message;
      }
    }
    return new Response(JSON.stringify({
      error: errorMessage,
      details: error instanceof Error ? error.message : error.toString(),
      timestamp: new Date().toISOString()
    }), {
      status: statusCode,
      headers: {
        ...corsHeaders,
        'Content-Type': 'application/json',
        'traceparent': tracer.getResponseTraceparent(),
      }
    });
  }
});
function appendOverlapDedup(buffer, chunk) {
  if (!buffer) return chunk;
  const max = Math.min(buffer.length, 256);
  for (let k = max; k > 0; k--) {
    if (buffer.slice(-k) === chunk.slice(0, k)) {
      return buffer + chunk.slice(k);
    }
  }
  return buffer + chunk;
}
function normalizeReasoningText(input) {
  let text = input.replace(/\r\n/g, "\n");
  text = text.replace(/\*+/g, "");
  text = text.replace(/[^\S\n]+/g, " ");
  text = text.replace(/\n{3,}/g, "\n\n");
  text = text.replace(/\s*:\s*/g, ": ");
  text = text.replace(/\s*,\s*/g, ", ");
  text = text.replace(/\s*\.\s*/g, ". ");
  text = text.replace(/ {2,}/g, " ").trim();
  try {
    const wordDedup = new RegExp("(\\b[\\p{L}0-9]+\\b)(?:\\s+\\1)+", "gu");
    text = text.replace(wordDedup, "$1");
    const phraseDedup = new RegExp("((?:\\b[\\p{L}0-9]+\\b\\s?){2,6})(?:\\s+\\1)+", "gu");
    text = text.replace(phraseDedup, "$1");
  } catch (e) { console.debug('[normalize] skip'); }
  return text;
}

