  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

/**
 * Calcula a distância de Levenshtein (edição) entre duas strings.
 *
 * @param a - Primeira string.
 * @param b - Segunda string.
 * @returns Número mínimo de inserções, remoções ou substituições para transformar `a` em `b`.
 *
 * @example
 * ```ts
 * levenshtein("gato", "rato"); // 1
 * ```
 */
export const levenshtein = (a: string, b: string): number => {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + cost,
      );
    }
  }
  return dp[m][n];
};

/**
 * Retorna um score de similaridade entre 0 e 1 para duas strings.
 *
 * Utiliza Levenshtein normalizado sobre os nomes após {@link normalizeName},
 * com bônus de +0.1 quando uma string é substring da outra.
 *
 * @param a - Primeira string (original, não normalizada).
 * @param b - Segunda string (original, não normalizada).
 * @returns Score de 0 (completamente diferentes) a 1 (idênticos).
 *
 * @example
 * ```ts
 * similarity("Bolo de chocolate", "Bolo Chocolate"); // ~0.85
 * similarity("Pão", "Queijo");                       // ~0.0
 * ```
 */
export const similarity = (a: string, b: string): number => {
  const na = normalizeName(a);
  const nb = normalizeName(b);
  if (!na || !nb) return 0;
  const dist = levenshtein(na, nb);
  const maxLen = Math.max(na.length, nb.length);
  const baseScore = 1 - dist / maxLen;
  const substrBonus = (na.includes(nb) || nb.includes(na)) ? 0.1 : 0;
  return Math.max(0, Math.min(1, baseScore + substrBonus));
};

